/// Bundled `minecraft-data` Java edition `blocks.json` files.
///
/// Each file is generated by PrismarineJS/minecraft-data and provides, for a
/// concrete game version:
/// * numeric block id;
/// * `minStateId` / `maxStateId` / `defaultState`;
/// * the ordered property definitions (`states`) used by the block.
///
/// Note: for Java these files intentionally do **not** contain the full
/// stateId -> property-value palette. State ids are therefore exposed as the
/// ranges defined by the source data, not synthesized property combinations.
const VERSIONS: &[(&str, &str)] = &[
    (
        "1.13.2",
        include_str!("../../../data/java_blocks_1.13.2.json"),
    ),
    (
        "1.14.4",
        include_str!("../../../data/java_blocks_1.14.4.json"),
    ),
    (
        "1.15.2",
        include_str!("../../../data/java_blocks_1.15.2.json"),
    ),
    (
        "1.16.1",
        include_str!("../../../data/java_blocks_1.16.1.json"),
    ),
    (
        "1.17.1",
        // minecraft-data publishes the 1.17 registry under the minor release
        // directory; the stable 1.17.1 block states are the same for these
        // schematic conversions.
        include_str!("../../../data/java_blocks_1.17.json"),
    ),
    (
        "1.18.2",
        include_str!("../../../data/java_blocks_1.18.json"),
    ),
    (
        "1.19.4",
        include_str!("../../../data/java_blocks_1.19.4.json"),
    ),
    (
        "1.20.1",
        include_str!("../../../data/java_blocks_1.20.1.json"),
    ),
    (
        "1.20.4",
        include_str!("../../../data/java_blocks_1.20.4.json"),
    ),
    (
        "1.21.1",
        include_str!("../../../data/java_blocks_1.21.1.json"),
    ),
];

/// Pre-flattening Java releases use the same namespaced block-state model in
/// schematic palettes, but do not have a separate bundled `blocks.json`
/// snapshot. Their compatibility mapping is provided by the legacy numeric
/// palette codec instead.
const LEGACY_JAVA_VERSIONS: &[&str] = &["1.7.10", "1.8.9", "1.9.4", "1.10.2", "1.11.2", "1.12.2"];

static REGISTRY: OnceLock<Vec<VersionBlockStates>> = OnceLock::new();

#[derive(Debug, Clone, Deserialize, Serialize)]
pub struct BlockPropertyDef {
    pub name: String,
    #[serde(rename = "type")]
    pub property_type: String,
    #[serde(rename = "num_values")]
    pub num_values: u32,
    #[serde(default)]
    pub values: Vec<String>,
}

#[derive(Debug, Clone, Deserialize, Serialize)]
pub struct JavaBlockStateDef {
    pub id: u32,
    pub name: String,
    #[serde(rename = "minStateId")]
    pub min_state_id: u32,
    #[serde(rename = "maxStateId")]
    pub max_state_id: u32,
    #[serde(rename = "defaultState")]
    pub default_state: u32,
    #[serde(default)]
    pub states: Vec<BlockPropertyDef>,
}

#[derive(Debug, Clone)]
pub struct VersionBlockStates {
    pub version: String,
    blocks: Vec<JavaBlockStateDef>,
    by_name: HashMap<String, usize>,
    by_state_id: HashMap<u32, usize>,
}

impl VersionBlockStates {
    fn parse(version: &str, raw: &str) -> Self {
        let blocks: Vec<JavaBlockStateDef> = serde_json::from_str(raw).unwrap_or_else(|error| {
            panic!("failed to parse bundled java_blocks_{version}.json: {error}")
        });

        let mut by_name = HashMap::with_capacity(blocks.len());
        let mut by_state_id = HashMap::new();

        for (index, block) in blocks.iter().enumerate() {
            by_name.entry(block.name.clone()).or_insert(index);
            for state_id in block.min_state_id..=block.max_state_id {
                by_state_id.entry(state_id).or_insert(index);
            }
        }

        Self {
            version: version.to_string(),
            blocks,
            by_name,
            by_state_id,
        }
    }

    pub fn block_by_name(&self, name: &str) -> Option<&JavaBlockStateDef> {
        let name = name.strip_prefix("minecraft:").unwrap_or(name);
        self.by_name.get(name).map(|index| &self.blocks[*index])
    }

    pub fn block_by_state_id(&self, state_id: u32) -> Option<&JavaBlockStateDef> {
        self.by_state_id
            .get(&state_id)
            .map(|index| &self.blocks[*index])
    }

    pub fn block_count(&self) -> usize {
        self.blocks.len()
    }
}

pub fn registry() -> &'static [VersionBlockStates] {
    REGISTRY.get_or_init(|| {
        VERSIONS
            .iter()
            .map(|(version, raw)| VersionBlockStates::parse(version, raw))
            .collect()
    })
}

pub fn versions() -> Vec<&'static str> {
    VERSIONS.iter().map(|(version, _)| *version).collect()
}

pub fn version(version: &str) -> Option<&'static VersionBlockStates> {
    registry().iter().find(|data| data.version == version)
}

/// Returns the protocol/DataVersion written into Java schematic formats.
///
/// The bundled block tables are keyed by the user-facing Minecraft version,
/// while the NBT formats store the numeric DataVersion. Keeping this mapping
/// next to the version registry prevents every writer from carrying its own
/// (and potentially inconsistent) table.
pub fn data_version(version: &str) -> Option<i32> {
    match version {
        "1.7.10" => Some(5),
        "1.8.9" => Some(47),
        "1.9.4" => Some(184),
        "1.10.2" => Some(512),
        "1.11.2" => Some(922),
        "1.12.2" => Some(1343),
        "1.13.2" => Some(1631),
        "1.14.4" => Some(1976),
        "1.15.2" => Some(2230),
        "1.16.1" => Some(2567),
        "1.17.1" => Some(2730),
        "1.18.2" => Some(2975),
        "1.19.4" => Some(3337),
        "1.20.1" => Some(3465),
        "1.20.4" => Some(3700),
        "1.21.1" => Some(3955),
        _ => None,
    }
}

pub fn is_legacy_java_version(version: &str) -> bool {
    LEGACY_JAVA_VERSIONS.contains(&version)
}

fn bare_block_name(name: &str) -> &str {
    name.strip_prefix("minecraft:").unwrap_or(name)
}

fn canonical_block_name(name: &str) -> String {
    format!("minecraft:{}", bare_block_name(name))
}

fn normalize_property_value(definition: &BlockPropertyDef, value: &str) -> Result<String, String> {
    let value = value.trim();
    match definition.property_type.as_str() {
        "bool" => match value.to_ascii_lowercase().as_str() {
            "0" | "false" => Ok("false".to_string()),
            "1" | "true" => Ok("true".to_string()),
            _ => Err(format!("expected boolean, found '{value}'")),
        },
        "int" => {
            let parsed = value
                .parse::<i32>()
                .map_err(|_| format!("expected integer, found '{value}'"))?;
            if !definition.values.is_empty() {
                if definition.values.iter().any(|candidate| candidate == value) {
                    Ok(value.to_string())
                } else {
                    Err(format!("value '{value}' is not in the target version"))
                }
            } else if parsed >= 0 && parsed < definition.num_values as i32 {
                Ok(parsed.to_string())
            } else {
                Err(format!("value '{value}' is outside the target range"))
            }
        }
        _ => {
            if definition.values.is_empty()
                || definition.values.iter().any(|candidate| candidate == value)
            {
                Ok(value.to_string())
            } else {
                Err(format!("value '{value}' is not in the target version"))
            }
        }
    }
}

fn compatibility_fallback(version: &str, name: &str) -> Option<String> {
    let before_1_17 = matches!(version, "1.13.2" | "1.14.4" | "1.15.2" | "1.16.1");
    let before_1_20 = matches!(
        version,
        "1.13.2" | "1.14.4" | "1.15.2" | "1.16.1" | "1.17.1" | "1.18.2" | "1.19.4"
    );
    let before_1_21 = matches!(
        version,
        "1.13.2"
            | "1.14.4"
            | "1.15.2"
            | "1.16.1"
            | "1.17.1"
            | "1.18.2"
            | "1.19.4"
            | "1.20.1"
            | "1.20.4"
    );

    match name {
        "grass" if matches!(version, "1.20.4" | "1.21.1") => Some("short_grass".to_string()),
        "short_grass" if !matches!(version, "1.20.4" | "1.21.1") => Some("grass".to_string()),
        "sign" if version != "1.13.2" => Some("oak_sign".to_string()),
        "wall_sign" if version != "1.13.2" => Some("oak_wall_sign".to_string()),
        "dirt_path" if before_1_17 => Some("grass_path".to_string()),
        "grass_path" if !before_1_17 => Some("dirt_path".to_string()),
        "deepslate" | "polished_deepslate" | "deepslate_bricks" | "deepslate_tiles"
            if before_1_17 =>
        {
            Some("stone".to_string())
        }
        "cobbled_deepslate" if before_1_17 => Some("cobblestone".to_string()),
        "tuff" if before_1_17 => Some("stone".to_string()),
        "sculk" | "sculk_catalyst" | "sculk_sensor" | "calibrated_sculk_sensor" if before_1_17 => {
            Some("stone".to_string())
        }
        "chiseled_bookshelf" if before_1_20 => Some("bookshelf".to_string()),
        "copper_bulb" if before_1_21 => Some("redstone_lamp".to_string()),
        "crafter" if before_1_21 => Some("crafting_table".to_string()),
        "trial_spawner" if before_1_21 => Some("spawner".to_string()),
        "vault" if before_1_21 => Some("chest".to_string()),
        "sniffer_egg" if before_1_20 => Some("stone".to_string()),
        "decorated_pot" if before_1_20 => Some("flower_pot".to_string()),
        "suspicious_sand" if before_1_20 => Some("sand".to_string()),
        "suspicious_gravel" if before_1_20 => Some("gravel".to_string()),
        "mud" | "packed_mud" | "mud_bricks" if before_1_20 => Some("dirt".to_string()),
        "mangrove_roots" | "muddy_mangrove_roots" if before_1_20 => Some("dirt".to_string()),
        "mangrove_propagule" if before_1_20 => Some("oak_sapling".to_string()),
        "bamboo" | "bamboo_sapling" if before_1_20 => Some("sugar_cane".to_string()),
        "bamboo_block" | "stripped_bamboo_block" if before_1_20 => Some("oak_log".to_string()),
        "blackstone" | "polished_blackstone" | "polished_blackstone_bricks" if before_1_17 => {
            Some("stone".to_string())
        }
        "crimson_nylium" | "warped_nylium" if before_1_17 => Some("netherrack".to_string()),
        "crimson_stem" | "warped_stem" | "crimson_hyphae" | "warped_hyphae" if before_1_17 => {
            Some("nether_bricks".to_string())
        }
        "soul_soil" if before_1_17 => Some("soul_sand".to_string()),
        "weeping_vines" | "twisting_vines" if before_1_17 => Some("vine".to_string()),
        "copper_ore" | "deepslate_copper_ore" if before_1_17 => Some("iron_ore".to_string()),
        "raw_copper_block"
        | "copper_block"
        | "exposed_copper"
        | "weathered_copper"
        | "oxidized_copper"
        | "cut_copper"
        | "exposed_cut_copper"
        | "weathered_cut_copper"
        | "oxidized_cut_copper"
        | "waxed_copper_block"
        | "waxed_exposed_copper"
        | "waxed_weathered_copper"
        | "waxed_oxidized_copper"
        | "waxed_cut_copper"
        | "waxed_exposed_cut_copper"
        | "waxed_weathered_cut_copper"
        | "waxed_oxidized_cut_copper"
            if before_1_17 =>
        {
            Some("iron_block".to_string())
        }
        "amethyst_block"
        | "budding_amethyst"
        | "small_amethyst_bud"
        | "medium_amethyst_bud"
        | "large_amethyst_bud"
        | "amethyst_cluster"
        | "tinted_glass"
            if before_1_17 =>
        {
            Some("glass".to_string())
        }
        _ if before_1_20 && name.starts_with("cherry_") => {
            let replacement = name.replacen("cherry_", "oak_", 1);
            if replacement.ends_with("_wall_sign") || replacement.ends_with("_wall_hanging_sign") {
                Some(sign_fallback_name(version, true))
            } else if replacement.ends_with("_sign") || replacement.ends_with("_hanging_sign") {
                Some(sign_fallback_name(version, false))
            } else {
                Some(replacement)
            }
        }
        _ if before_1_20 && name.starts_with("sniffer_") => Some("stone".to_string()),
        _ => generic_compatibility_fallback(version, name),
    }
}

fn generic_compatibility_fallback(version: &str, name: &str) -> Option<String> {
    let before_1_17 = matches!(version, "1.13.2" | "1.14.4" | "1.15.2" | "1.16.1");
    let before_1_20 = matches!(
        version,
        "1.13.2" | "1.14.4" | "1.15.2" | "1.16.1" | "1.17.1" | "1.18.2" | "1.19.4"
    );

    if before_1_20 {
        if name.ends_with("_wall_hanging_sign") || name.ends_with("_wall_sign") {
            return Some(sign_fallback_name(version, true));
        }
        if name.ends_with("_hanging_sign") || name.ends_with("_sign") {
            return Some(sign_fallback_name(version, false));
        }
        if name == "stripped_cherry_log" || name == "stripped_cherry_wood" {
            return Some(name.replacen("stripped_cherry", "stripped_oak", 1));
        }
        if name.starts_with("cherry_") {
            return Some(name.replacen("cherry_", "oak_", 1));
        }
        if name.starts_with("mangrove_") {
            return Some(name.replacen("mangrove_", "oak_", 1));
        }
        if name == "bamboo_planks" || name == "bamboo_mosaic" {
            return Some("oak_planks".to_string());
        }
    }

    if before_1_17 {
        if let Some(ore) = name.strip_prefix("deepslate_") {
            return Some(match ore {
                "coal_ore" | "iron_ore" | "gold_ore" | "diamond_ore" | "emerald_ore"
                | "lapis_ore" | "redstone_ore" => ore.to_string(),
                "copper_ore" => "iron_ore".to_string(),
                _ => "stone".to_string(),
            });
        }
        if name.ends_with("_stairs") {
            return Some("cobblestone_stairs".to_string());
        }
        if name.ends_with("_slab") {
            return Some("stone_slab".to_string());
        }
        if name.ends_with("_wall_hanging_sign") {
            return Some(sign_fallback_name(version, true));
        }
        if name.ends_with("_wall") {
            return Some("cobblestone_wall".to_string());
        }
        if name.ends_with("_wall_sign") {
            return Some(sign_fallback_name(version, true));
        }
        if name.ends_with("_hanging_sign") || name.ends_with("_sign") {
            return Some(sign_fallback_name(version, false));
        }
        if name.ends_with("_fence_gate") {
            return Some("oak_fence_gate".to_string());
        }
        if name.ends_with("_fence") {
            return Some("oak_fence".to_string());
        }
        if name.ends_with("_door") {
            return Some("oak_door".to_string());
        }
        if name.ends_with("_trapdoor") {
            return Some("oak_trapdoor".to_string());
        }
        if name.ends_with("_button") {
            return Some("stone_button".to_string());
        }
        if name.ends_with("_pressure_plate") {
            return Some("stone_pressure_plate".to_string());
        }
        if name.ends_with("_planks") {
            return Some("oak_planks".to_string());
        }
        if name.starts_with("potted_") {
            return Some("flower_pot".to_string());
        }
        if name.ends_with("_leaves") {
            return Some("oak_leaves".to_string());
        }
        if name.ends_with("_sapling") {
            return Some("oak_sapling".to_string());
        }
        if name.ends_with("_log") || name.ends_with("_wood") {
            return Some("oak_log".to_string());
        }
        if name.ends_with("_candle_cake") {
            return Some("cake".to_string());
        }
        if name.ends_with("_candle") {
            return Some("torch".to_string());
        }
        if name.ends_with("_ore") {
            return Some("coal_ore".to_string());
        }
        if matches!(
            name,
            "torchflower"
                | "torchflower_crop"
                | "pitcher_crop"
                | "pitcher_plant"
                | "cornflower"
                | "wither_rose"
                | "lily_of_the_valley"
                | "sweet_berry_bush"
                | "glow_lichen"
                | "cave_vines"
                | "cave_vines_plant"
                | "spore_blossom"
                | "azalea"
                | "flowering_azalea"
                | "moss_carpet"
                | "pink_petals"
                | "big_dripleaf"
                | "small_dripleaf"
                | "hanging_roots"
                | "sculk_vein"
                | "sculk_shrieker"
                | "nether_sprouts"
                | "warped_fungus"
                | "crimson_fungus"
                | "weeping_vines_plant"
                | "twisting_vines_plant"
        ) {
            return Some("grass".to_string());
        }
        if matches!(name, "soul_fire") {
            return Some("fire".to_string());
        }
        if matches!(
            name,
            "soul_torch" | "soul_wall_torch" | "lantern" | "soul_lantern"
        ) {
            return Some("torch".to_string());
        }
        if matches!(
            name,
            "water_cauldron" | "lava_cauldron" | "powder_snow_cauldron"
        ) {
            return Some("cauldron".to_string());
        }
        if matches!(name, "piglin_head" | "piglin_wall_head") {
            return Some("player_head".to_string());
        }
        if name == "light" {
            return Some("air".to_string());
        }
        if name == "chain" {
            return Some("iron_bars".to_string());
        }
        if name == "basalt" || name == "polished_basalt" || name == "smooth_basalt" {
            return Some("stone".to_string());
        }
        if name == "scaffolding" || name == "jigsaw" || name == "target" {
            return Some("stone".to_string());
        }
        if matches!(name, "barrel" | "bee_nest" | "beehive") {
            return Some("chest".to_string());
        }
        if matches!(name, "smoker" | "blast_furnace") {
            return Some("furnace".to_string());
        }
        if matches!(
            name,
            "cartography_table"
                | "fletching_table"
                | "grindstone"
                | "lectern"
                | "smithing_table"
                | "stonecutter"
                | "loom"
        ) {
            return Some("crafting_table".to_string());
        }
        if name == "bell" || name == "composter" {
            return Some("cauldron".to_string());
        }
        if name == "campfire" || name == "soul_campfire" {
            return Some("fire".to_string());
        }
        if name == "warped_wart_block" || name == "shroomlight" {
            return Some("nether_bricks".to_string());
        }
        if name.ends_with("_roots") || name.ends_with("_fungus") {
            return Some("grass".to_string());
        }
        if name.ends_with("_head") {
            return Some("skull".to_string());
        }
        if name == "honey_block" || name == "honeycomb_block" {
            return Some("slime_block".to_string());
        }
        if name == "quartz_bricks" {
            return Some("quartz_block".to_string());
        }
        if name == "moss_block" || name == "rooted_dirt" {
            return Some("dirt".to_string());
        }
        if name.starts_with("chiseled_deepslate")
            || name.starts_with("cracked_deepslate")
            || name == "infested_deepslate"
        {
            return Some("stone".to_string());
        }
        if name.ends_with("_froglight") {
            return Some("glowstone".to_string());
        }
        if name == "netherite_block" || name == "raw_iron_block" {
            return Some("iron_block".to_string());
        }
        if name == "raw_gold_block" {
            return Some("gold_block".to_string());
        }
        if name == "ancient_debris" {
            return Some("iron_block".to_string());
        }
        if matches!(name, "crying_obsidian" | "respawn_anchor") {
            return Some("obsidian".to_string());
        }
        if name == "lodestone" {
            return Some("stone".to_string());
        }
        if name.contains("blackstone") || name.contains("nether_bricks") {
            return Some("stone".to_string());
        }
        if name == "candle" || name.ends_with("_candle") {
            return Some("torch".to_string());
        }
        if name == "candle_cake" || name.ends_with("_candle_cake") {
            return Some("cake".to_string());
        }
        if name == "calcite" {
            return Some("stone".to_string());
        }
        if name == "powder_snow" {
            return Some("snow".to_string());
        }
        if name == "lightning_rod" {
            return Some("iron_bars".to_string());
        }
        if name.contains("dripstone") || name == "pointed_dripstone" {
            return Some("stone".to_string());
        }
        if name == "frogspawn" {
            return Some("water".to_string());
        }
        if name == "reinforced_deepslate" {
            return Some("stone".to_string());
        }
        if name.ends_with("_nylium") {
            return Some("netherrack".to_string());
        }
        if name.ends_with("_stem") || name.ends_with("_hyphae") {
            return Some("nether_bricks".to_string());
        }
        if name.ends_with("_roots") || name.ends_with("_fungus") {
            return Some("grass".to_string());
        }
        if name.ends_with("_block") && name.contains("copper") {
            return Some("iron_block".to_string());
        }
        if name.contains("copper") {
            return Some("iron_block".to_string());
        }
        if name.ends_with("_concrete") || name.ends_with("_concrete_powder") {
            return Some(
                name.replace("_concrete_powder", "_wool")
                    .replace("_concrete", "_wool"),
            );
        }
    }

    None
}

fn sign_fallback_name(version: &str, wall: bool) -> String {
    if version == "1.13.2" {
        if wall {
            "wall_sign".to_string()
        } else {
            "sign".to_string()
        }
    } else if wall {
        "oak_wall_sign".to_string()
    } else {
        "oak_sign".to_string()
    }
}

fn force_compatibility_fallback(version: &str, name: &str) -> bool {
    // A few bundled minecraft-data snapshots contain blocks from a nearby
    // release. Keep the user-facing version boundary authoritative for
    // blocks whose introduction/removal is well-defined.
    let before_1_20 = matches!(
        version,
        "1.13.2" | "1.14.4" | "1.15.2" | "1.16.1" | "1.17.1" | "1.18.2" | "1.19.4"
    );
    let before_1_20_4 = !matches!(version, "1.20.4" | "1.21.1");

    (before_1_20 && (name.starts_with("cherry_") || name.starts_with("sniffer_")))
        || (before_1_20_4 && name == "short_grass")
        || (!before_1_20_4 && name == "grass")
}

/// Normalize one Java-style block state for a concrete Java version.
///
/// Java minecraft-data tables store unnamespaced names, whereas the unified
/// model uses namespaced ids. Only properties defined by the target version
/// are retained; values are validated and booleans are canonicalized to
/// true/false. The bundled tables do not contain every state-id combination,
/// so this function deliberately works with names and property definitions
/// rather than pretending to reconstruct a numeric state id.
pub fn normalize_block_for_java(
    target_version: &str,
    block: &BlockData,
) -> Result<Arc<BlockData>, SchematicError> {
    if is_legacy_java_version(target_version) {
        return normalize_block_for_legacy(target_version, block);
    }

    let target = version(target_version).ok_or_else(|| {
        SchematicError::MissingField(format!("unknown Java target version: {target_version}"))
    })?;

    let source_name = bare_block_name(block.id.name.as_ref());
    let target_name = if !force_compatibility_fallback(target_version, source_name)
        && target.block_by_name(source_name).is_some()
    {
        source_name.to_string()
    } else if let Some(fallback) = compatibility_fallback(target_version, source_name) {
        fallback
    } else {
        return Err(SchematicError::MissingField(format!(
            "block minecraft:{source_name} is unavailable in Java {target_version}"
        )));
    };

    let target_block = target.block_by_name(&target_name).ok_or_else(|| {
        SchematicError::MissingField(format!(
            "compatibility block minecraft:{target_name} is unavailable in Java {target_version}"
        ))
    })?;

    let mut properties = BTreeMap::new();
    for (name, value) in &block.properties {
        let property_name = name.as_ref();
        let Some(definition) = target_block
            .states
            .iter()
            .find(|definition| definition.name == property_name)
        else {
            continue;
        };

        match normalize_property_value(definition, value.as_ref()) {
            Ok(normalized) => {
                properties.insert(
                    Arc::<str>::from(property_name),
                    Arc::<str>::from(normalized),
                );
            }
            Err(reason) => {
                // A palette may carry a state value introduced after the
                // target release. Omitting that property selects the target
                // block's default state and keeps the rest of the schematic
                // convertible.
                eprintln!(
                    "[java-map] dropping unsupported property {property_name}={value} for minecraft:{target_name} in Java {target_version}: {reason}"
                );
            }
        }
    }

    Ok(Arc::new(BlockData {
        id: BlockId {
            name: Arc::<str>::from(canonical_block_name(&target_name)),
        },
        properties,
    }))
}

/// Short alias for callers that normalize individual block states.
pub fn normalize_for_java(
    target_version: &str,
    block: &BlockData,
) -> Result<Arc<BlockData>, SchematicError> {
    normalize_block_for_java(target_version, block)
}

/// Normalize every block in a schematic while retaining positions and
/// metadata. This is intentionally a pure transformation so callers can
/// choose a different Java target version for each output conversion.
pub fn normalize_schematic_for_java(
    target_version: &str,
    data: &SchematicData,
) -> Result<SchematicData, SchematicError> {
    if is_legacy_java_version(target_version) {
        return normalize_schematic_for_legacy(target_version, data);
    }

    // Validate the target even for an empty schematic, producing a useful
    // version error before any output writer is invoked.
    version(target_version).ok_or_else(|| {
        SchematicError::MissingField(format!("unknown Java target version: {target_version}"))
    })?;

    let mut normalized_cache: HashMap<BlockData, Arc<BlockData>> = HashMap::new();
    let blocks = data
        .blocks
        .elements
        .iter()
        .map(|block| {
            let normalized = if let Some(cached) = normalized_cache.get(block.block.as_ref()) {
                cached.clone()
            } else {
                let normalized = normalize_block_for_java(target_version, &block.block)?;
                normalized_cache.insert(block.block.as_ref().clone(), normalized.clone());
                normalized
            };
            Ok(BlockStatePos {
                pos: block.pos,
                block: normalized,
            })
        })
        .collect::<Result<_, SchematicError>>()?;

    Ok(SchematicData::new(
        crate::utils::block_state_pos_list::BlockStatePosList { elements: blocks },
        data.tile_entities_list.clone(),
        data.entities_list.clone(),
        data.size,
    ))
}

#[tauri::command]
pub fn get_java_block_versions() -> Vec<&'static str> {
    LEGACY_JAVA_VERSIONS
        .iter()
        .copied()
        .chain(versions())
        .collect()
}

#[tauri::command]
pub fn get_java_block_state(version: String, name: String) -> Result<JavaBlockStateDef, String> {
    let data = crate::utils::minecraft_data::java_block_states::version(&version)
        .ok_or_else(|| format!("unknown java version: {version}"))?;
    data.block_by_name(&name)
        .cloned()
        .ok_or_else(|| format!("unknown block {name} for version {version}"))
}

#[tauri::command]
pub fn get_java_block_by_state_id(
    version: String,
    state_id: u32,
) -> Result<JavaBlockStateDef, String> {
    let data = crate::utils::minecraft_data::java_block_states::version(&version)
        .ok_or_else(|| format!("unknown java version: {version}"))?;
    data.block_by_state_id(state_id)
        .cloned()
        .ok_or_else(|| format!("unknown state id {state_id} for version {version}"))
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::collections::BTreeMap;

    #[test]
    fn loads_all_bundled_java_versions() {
        let registry = registry();
        assert_eq!(registry.len(), VERSIONS.len());
        for data in registry {
            assert!(
                data.block_count() > 0,
                "empty registry for {}",
                data.version
            );
        }
    }

    #[test]
    fn resolves_state_id_ranges_and_properties() {
        let v1_13_2 = version("1.13.2").expect("1.13.2 registry");

        let oak_log = v1_13_2.block_by_name("oak_log").unwrap();
        assert_eq!((oak_log.min_state_id, oak_log.max_state_id), (72, 74));
        assert_eq!(oak_log.default_state, 73);
        assert_eq!(v1_13_2.block_by_state_id(73).unwrap().name, "oak_log");
        assert_eq!(v1_13_2.block_by_state_id(75).unwrap().name, "spruce_log");

        let oak_stairs = v1_13_2.block_by_name("oak_stairs").unwrap();
        assert_eq!(oak_stairs.states.len(), 4);
        assert_eq!(oak_stairs.states[0].name, "facing");
        assert_eq!(
            oak_stairs.states[0].values,
            vec!["north", "south", "west", "east"]
        );
    }

    #[test]
    fn normalizes_namespaced_blocks_and_boolean_values() {
        let mut properties = BTreeMap::new();
        properties.insert(Arc::<str>::from("snowy"), Arc::<str>::from("1"));
        properties.insert(
            Arc::<str>::from("removed_by_newer_java"),
            Arc::<str>::from("x"),
        );
        let block = BlockData {
            id: BlockId {
                name: Arc::<str>::from("minecraft:grass_block"),
            },
            properties,
        };

        let normalized = normalize_block_for_java("1.13.2", &block).unwrap();
        assert_eq!(normalized.id.name.as_ref(), "minecraft:grass_block");
        assert_eq!(
            normalized.properties.get("snowy").map(AsRef::as_ref),
            Some("true")
        );
        assert!(!normalized.properties.contains_key("removed_by_newer_java"));
    }

    #[test]
    fn drops_property_values_unavailable_in_target_version() {
        let mut properties = BTreeMap::new();
        properties.insert(Arc::<str>::from("snowy"), Arc::<str>::from("not-a-boolean"));
        let block = BlockData {
            id: BlockId {
                name: Arc::<str>::from("minecraft:grass_block"),
            },
            properties,
        };

        let normalized = normalize_for_java("1.13.2", &block).unwrap();
        assert_eq!(normalized.id.name.as_ref(), "minecraft:grass_block");
        assert!(!normalized.properties.contains_key("snowy"));
    }

    #[test]
    fn applies_explicit_legacy_compatibility_fallback() {
        let block = BlockData {
            id: BlockId {
                name: Arc::<str>::from("dirt_path"),
            },
            properties: BTreeMap::new(),
        };

        let normalized = normalize_block_for_java("1.13.2", &block).unwrap();
        assert_eq!(normalized.id.name.as_ref(), "minecraft:grass_path");
    }

    #[test]
    fn normalizes_common_blocks_for_every_bundled_version() {
        let mut properties = BTreeMap::new();
        properties.insert(Arc::<str>::from("axis"), Arc::<str>::from("y"));
        let block = BlockData {
            id: BlockId {
                name: Arc::<str>::from("minecraft:oak_log"),
            },
            properties,
        };

        for target_version in versions() {
            let normalized = normalize_for_java(target_version, &block)
                .unwrap_or_else(|error| panic!("{target_version}: {error}"));
            assert_eq!(normalized.id.name.as_ref(), "minecraft:oak_log");
            assert_eq!(
                normalized.properties.get("axis").map(AsRef::as_ref),
                Some("y")
            );
        }
    }

    #[test]
    fn supports_java_1_20_1_data_version() {
        assert!(version("1.20.1").is_some());
        assert_eq!(data_version("1.20.1"), Some(3465));

        let block = BlockData {
            id: BlockId {
                name: Arc::<str>::from("minecraft:cherry_planks"),
            },
            properties: BTreeMap::new(),
        };
        let normalized = normalize_for_java("1.20.1", &block).unwrap();
        assert_eq!(normalized.id.name.as_ref(), "minecraft:cherry_planks");
    }

    #[test]
    fn supports_java_1_17_and_1_18_target_tables() {
        assert_eq!(data_version("1.17.1"), Some(2730));
        assert_eq!(data_version("1.18.2"), Some(2975));

        let block = BlockData {
            id: BlockId {
                name: Arc::<str>::from("minecraft:deepslate"),
            },
            properties: BTreeMap::new(),
        };
        assert_eq!(
            normalize_for_java("1.17.1", &block)
                .unwrap()
                .id
                .name
                .as_ref(),
            "minecraft:deepslate"
        );
        assert_eq!(
            normalize_for_java("1.18.2", &block)
                .unwrap()
                .id
                .name
                .as_ref(),
            "minecraft:deepslate"
        );
    }

    #[test]
    fn supports_pre_flattening_java_targets_through_legacy_codec() {
        assert_eq!(data_version("1.7.10"), Some(5));
        assert_eq!(data_version("1.12.2"), Some(1343));
        assert!(get_java_block_versions().starts_with(&["1.7.10", "1.8.9"]));

        let block = BlockData {
            id: BlockId {
                name: Arc::<str>::from("minecraft:cherry_planks"),
            },
            properties: BTreeMap::new(),
        };
        let normalized = normalize_for_java("1.12.2", &block).unwrap();
        assert_eq!(normalized.id.name.as_ref(), "minecraft:oak_planks");
    }

    #[test]
    fn downgrades_modern_blocks_for_older_java_targets() {
        let cases = [
            ("1.13.2", "minecraft:cherry_planks", "minecraft:oak_planks"),
            ("1.13.2", "minecraft:bamboo", "minecraft:sugar_cane"),
            ("1.13.2", "minecraft:cherry_sign", "minecraft:sign"),
            (
                "1.13.2",
                "minecraft:cherry_wall_sign",
                "minecraft:wall_sign",
            ),
            ("1.14.4", "minecraft:sign", "minecraft:oak_sign"),
            ("1.14.4", "minecraft:cherry_sign", "minecraft:oak_sign"),
            ("1.19.4", "minecraft:cherry_sign", "minecraft:oak_sign"),
            ("1.20.1", "minecraft:short_grass", "minecraft:grass"),
            ("1.20.4", "minecraft:grass", "minecraft:short_grass"),
            ("1.16.1", "minecraft:amethyst_block", "minecraft:glass"),
            ("1.19.4", "minecraft:sniffer_egg", "minecraft:stone"),
            ("1.19.4", "minecraft:crafter", "minecraft:crafting_table"),
        ];

        for (version, source, expected) in cases {
            let block = BlockData {
                id: BlockId {
                    name: Arc::<str>::from(source),
                },
                properties: BTreeMap::new(),
            };
            let normalized = normalize_for_java(version, &block)
                .unwrap_or_else(|error| panic!("{version} {source}: {error}"));
            assert_eq!(normalized.id.name.as_ref(), expected);
        }
    }

    #[test]
    fn rejects_unknown_target_block_and_version() {
        let block = BlockData {
            id: BlockId {
                name: Arc::<str>::from("minecraft:not_a_block"),
            },
            properties: BTreeMap::new(),
        };

        let error = normalize_block_for_java("1.21.1", &block).unwrap_err();
        assert!(error.to_string().contains("not_a_block"));

        let error = normalize_block_for_java("1.18.1", &block).unwrap_err();
        assert!(error.to_string().contains("unknown Java target version"));
    }
}
